  assert.notEqual(first.document,third.document);assert.equal(frozenMutation.error?.name,'TypeError');assert.equal(changedCopy.error?.name,'TypeError');
  assert.equal(calls,0);for(const row of refusals){sameOutcome(row.before,row.current);assert.equal(row.current.error?.name,'TypeError',row.label);}
  assert.deepEqual(currentLimit,beforeLimit);visible(currentLimit,limitSource,'Rust');sameOutcome(over.before,over.current);assert.equal(over.current.error?.name,'TypeError');
});

